-- Run independently after the full batch, including after any timeout/error. Read-only.
SELECT 'POST_ROLLBACK_PROBE_ROWS_ABSENT' AS check_name, 1 / CASE WHEN (NOT EXISTS(SELECT 1 FROM public.debate_v3_events WHERE id='de-69ddcb067b431a666ff395d98d00473d' OR owner_id IN ('10000000-0000-4000-8000-000000009909','10000000-0000-4000-8000-000000009908')) AND NOT EXISTS(SELECT 1 FROM public.debate_v3_receipts WHERE event_id='de-69ddcb067b431a666ff395d98d00473d' OR actor_id IN ('10000000-0000-4000-8000-000000009909','10000000-0000-4000-8000-000000009908')) AND NOT EXISTS(SELECT 1 FROM public.debate_v3_audit WHERE event_id='de-69ddcb067b431a666ff395d98d00473d') AND NOT EXISTS(SELECT 1 FROM public.debate_v3_outbox WHERE id='de-69ddcb067b431a666ff395d98d00473d:rollback-only-job' OR event_id='de-69ddcb067b431a666ff395d98d00473d')) THEN 1 ELSE 0 END AS passed;
SELECT jsonb_build_object('checkpoint','DML_ROLLBACK_ROWS_ABSENT','targetProjectMustBeVerifiedExternally','hlzqmreeoghbldnhlybr','eventId','de-69ddcb067b431a666ff395d98d00473d','actorId','10000000-0000-4000-8000-000000009909','providerCalls',0,'actualPermissionErrorProbes',false,'nativeConcurrentConnections',false,'catalogHash',(SELECT md5(coalesce(jsonb_agg(to_jsonb(c) ORDER BY room_key),'[]'::jsonb)::text) FROM private.study_room_catalog c),'catalog_auditHash',(SELECT md5(coalesce(jsonb_agg(to_jsonb(c) ORDER BY room_key,revision),'[]'::jsonb)::text) FROM private.study_room_catalog_audit c),'ledgerHash',(SELECT md5(coalesce(jsonb_agg(jsonb_build_object('version',version,'name',name) ORDER BY version),'[]'::jsonb)::text) FROM supabase_migrations.schema_migrations),'admissionsHash',(SELECT md5(coalesce(jsonb_agg(to_jsonb(c) ORDER BY request_id),'[]'::jsonb)::text) FROM private.study_room_admissions c),'admission_commandsHash',(SELECT md5(coalesce(jsonb_agg(to_jsonb(c) ORDER BY actor_user_id,command_id),'[]'::jsonb)::text) FROM private.study_room_admission_commands c),'debateFunctionCount',(SELECT count(*) FROM pg_proc p JOIN pg_namespace n ON n.oid=p.pronamespace WHERE n.nspname='public' AND p.proname LIKE 'debate_v3_%')) AS rollback_probe;
